import { test, expect } from '@playwright/test';

test.describe('Total Price Update on Quantity Change', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/checkout');
  });

  test('should update total price when quantity is increased', async ({ page }) => {
    // Verify initial total price is displayed
    const totalPrice = page.getByText('Total: $10.00');
    await expect(totalPrice).toBeVisible();

    // Verify initial quantity is displayed
    const quantityInput = page.getByLabel('Quantity');
    await expect(quantityInput).toBeVisible();
    const initialQuantity = await quantityInput.evaluate((el) => el.value);
    expect(initialQuantity).toBe('1');

    // Verify initial price is correct
    const priceElement = page.getByText('Price: $10.00');
    await expect(priceElement).toBeVisible();

    // Set up intercept for API call
    await page.route('**/api/products/123/price', (route) => {
      route.continue();
    });

    // Increase quantity to 3
    const quantityInput = page.getByLabel('Quantity');
    await quantityInput.fill('3');

    // Verify total price updates
    const updatedTotalPrice = page.getByText('Total: $30.00');
    await expect(updatedTotalPrice).toBeVisible();

    // Verify price element updates
    const updatedPriceElement = page.getByText('Price: $30.00');
    await expect(updatedPriceElement).toBeVisible();

    // Verify quantity input reflects new value
    await expect(quantityInput).toHaveValue('3');
  });

  test('should update total price when quantity is decreased', async ({ page }) => {
    // Verify initial total price is displayed
    const totalPrice = page.getByText('Total: $10.00');
    await expect(totalPrice).toBeVisible();

    // Verify initial quantity is displayed
    const quantityInput = page.getByLabel('Quantity');
    await expect(quantityInput).toBeVisible();
    const initialQuantity = await quantityInput.evaluate((el) => el.value);
    expect(initialQuantity).toBe('1');

    // Verify initial price is correct
    const priceElement = page.getByText('Price: $10.00');
    await expect(priceElement).toBeVisible();

    // Set up intercept for API call
    await page.route('**/api/products/123/price', (route) => {
      route.continue();
    });

    // Decrease quantity to 0
    const quantityInput = page.getByLabel('Quantity');
    await quantityInput.fill('0');

    // Verify total price updates
    const updatedTotalPrice = page.getByText('Total: $0.00');
    await expect(updatedTotalPrice).toBeVisible();

    // Verify price element updates
    const updatedPriceElement = page.getByText('Price: $0.00');
    await expect(updatedPriceElement).toBeVisible();

    // Verify quantity input reflects new value
    await expect(quantityInput).toHaveValue('0');
  });
});
